def transform(g):
 h,w=len(g),len(g[0]); out=[[0]*(w//3) for _ in range(h//3)]
 for c in set(x for row in g for x in row)-{0,5}:
  pts={(r,j) for r,row in enumerate(g) for j,x in enumerate(row) if x==c}
  while pts:
   stack=[pts.pop()]; comp=[]
   while stack:
    r,j=stack.pop(); comp.append((r,j))
    for q in ((r-1,j),(r+1,j),(r,j-1),(r,j+1)):
     if q in pts: pts.remove(q); stack.append(q)
   if len(comp)>=3:
    rr=(min(a for a,b in comp)+max(a for a,b in comp))//2
    cc=(min(b for a,b in comp)+max(b for a,b in comp))//2
    out[rr//3][cc//3]=c
 return out
